		/** 
		 * Tests creating a new Merchant.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a Merchant");

			StringBuilder msg = new StringBuilder( "-- Failed to create a Merchant" );

			try {            
				Merchant entity = MerchantService.getMerchantInstance().createMerchant( generateNewEntity() );
				thePrimaryKey = entity.getMerchantId();
				LOGGER.info( "-- Successfully created a Merchant with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a Merchant. 
		 */
		public Merchant testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created Merchant" );

			Merchant entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read Merchant with primary key" );
			msg.append( thePrimaryKey );
			
			MerchantFetchOneSummary fetchOneSummary = new MerchantFetchOneSummary( thePrimaryKey );

			try {
				entity = MerchantService.getMerchantInstance().getMerchant( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found Merchant " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a Merchant.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a Merchant." );

			StringBuilder msg = new StringBuilder( "Failed to update a Merchant : " );        
			Merchant entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created Merchant." );

				// for use later on...
				thePrimaryKey = entity.getMerchantId();

				MerchantService proxy = MerchantService.getMerchantInstance();            
				proxy.updateMerchant( entity );   

				LOGGER.info( "-- Successfully saved Merchant - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a Merchant.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created Merchant." );

			try{
			    Merchant entity = testRead(); 
				MerchantService.getMerchantInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted Merchant with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete Merchant with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all Merchants.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of Merchants:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all Merchant : " );        
			List<Merchant> collection  = null;

			try {
				// call the static get method on the MerchantService
				collection = MerchantService.getMerchantInstance().getAllMerchant();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					Merchant entity = null;            
					Iterator<Merchant> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getMerchantId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

